test('recordLogin sets last_login_at to now on the active user', (t, done) => {
  const before = Date.now();
  recordLogin('ada@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user.id, 1);
    const at = Date.parse(user.last_login_at);
    assert.ok(at >= before && at <= Date.now());
    new UserRepository().findById(1).then((stored) => {
      assert.equal(stored.last_login_at, user.last_login_at);
      done();
    }, done);
  });
});

test('recordLogin leaves soft-deleted users untouched', (t, done) => {
  recordLogin('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    new UserRepository().findById(3).then((stored) => {
      assert.equal(stored.last_login_at, undefined);
      done();
    }, done);
  });
});
